#!/usr/bin/env python3
"""Separate what the user actually asked from text the tools inject into the user turn."""

from __future__ import annotations

import re

REQUEST_TEXT_LIMIT = 4000

# Whole-turn markers: the turn is written by the tool, not by the user.
INJECTED_TURN_PREFIXES = (
    "this session is being continued from a previous conversation",
    "caveat: the messages below were generated by the user while running local commands",
    "<local-command-stdout>",
    "<local-command-stderr>",
    "<local-command-caveat>",
    "<task-notification>",
    "<environment_context>",
    "# agents.md instructions",
)

# Blocks the tool inserts around or inside a user turn.
INJECTED_BLOCK_PATTERNS = (
    re.compile(r"<system-reminder>.*?</system-reminder>", re.IGNORECASE | re.DOTALL),
    re.compile(r"<local-command-[a-z]+>.*?</local-command-[a-z]+>", re.IGNORECASE | re.DOTALL),
    re.compile(r"<task-notification>.*?</task-notification>", re.IGNORECASE | re.DOTALL),
    re.compile(r"<environment_context>.*?</environment_context>", re.IGNORECASE | re.DOTALL),
)

COMMAND_NAME_PATTERN = re.compile(r"<command-name>(.*?)</command-name>", re.IGNORECASE | re.DOTALL)
COMMAND_ARGS_PATTERN = re.compile(r"<command-args>(.*?)</command-args>", re.IGNORECASE | re.DOTALL)
COMMAND_TAG_PATTERN = re.compile(r"<command-(?:message|name|args)>.*?</command-(?:message|name|args)>", re.IGNORECASE | re.DOTALL)


def is_injected_turn(text: str) -> bool:
    lowered = str(text or "").lstrip().lower()
    return any(lowered.startswith(prefix) for prefix in INJECTED_TURN_PREFIXES)


def clean_request_text(text: str, *, limit: int = REQUEST_TEXT_LIMIT) -> str:
    """Return the user's own words, or "" when the turn holds none.

    A slash command turn becomes "/name args". Pasted content is kept, because
    the user chose to send it.
    """
    raw = str(text or "")
    if not raw.strip() or is_injected_turn(raw):
        return ""
    command_names = [match.strip() for match in COMMAND_NAME_PATTERN.findall(raw) if match.strip()]
    command_args = [match.strip() for match in COMMAND_ARGS_PATTERN.findall(raw) if match.strip()]
    for pattern in INJECTED_BLOCK_PATTERNS:
        raw = pattern.sub(" ", raw)
    raw = COMMAND_TAG_PATTERN.sub(" ", raw)
    if command_names:
        command = " ".join([command_names[0], *command_args]).strip()
        raw = f"{command}\n{raw}"
    cleaned = raw.strip()
    if is_injected_turn(cleaned):
        return ""
    if len(cleaned) > limit:
        cleaned = cleaned[:limit].rstrip() + "…"
    return cleaned
